    "america", "american", "europe", "european", "africa", "african", "asia", "asian", "australia", "canada",
    "london", "paris", "tokyo", "berlin", "india", "china", "japan", "france", "germany", "mexico", "brazil",
    "christmas", "easter", "thanksgiving", "halloween", "ramadan", "hanukkah",
    "google", "microsoft", "apple", "amazon", "facebook", "instagram", "youtube", "netflix", "linkedin", "twitter",
