      description: "Space before punctuation",
      category: CATEGORIES.TYPOGRAPHY,
      severity: "warning",
      autocorrect: true,
      pattern: /([A-Za-z0-9]) +([,.!?;:])(?!\S*[,.!?;:]\s*$)/g,
      handler: (m, text) => {
        // Ellipsis / emoticon / smiley guard: "wait ..." or ":)" or " :"
        const after = text.slice(m.index + m[0].length, m.index + m[0].length + 2);
        if (m[2] === ":" && /^[()\-DPp]/.test(after)) return null;
        if (m[2] === "." && after.startsWith("..")) return null;
        return { message: `Remove the space before "${m[2]}".`, shortMessage: "Spacing", replacements: [`${m[1]}${m[2]}`] };
      },
